-- Verified four-brand catalog import; unavailable owner-review drafts never appear publicly
BEGIN;
SET LOCAL lock_timeout='5s';
CREATE TEMP TABLE four_catalog_before ON COMMIT DROP AS SELECT jsonb_build_object(
