DO $identity$ BEGIN
IF NOT EXISTS(SELECT 1 FROM public.cafes WHERE id='7f28312f-4df2-4a1d-bedd-34b73f415307' AND slug='brand-c138e578b03c' AND status='active' AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Brand identity changed: rast';END IF;
IF NOT EXISTS(SELECT 1 FROM public.cafes WHERE id='6d01bd09-c7e0-4307-8cfb-93171d69d9db' AND slug='brand-5e0a98e765d2' AND status='active' AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Brand identity changed: black-drop';END IF;
IF NOT EXISTS(SELECT 1 FROM public.cafes WHERE id='a3c65c66-d5de-41e2-a2c7-0cc451a92bf3' AND slug='brand-f9e223695585' AND status='active' AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Brand identity changed: once';END IF;
IF NOT EXISTS(SELECT 1 FROM public.cafes WHERE id='318df308-e39f-4ef2-a0fd-05c126720d82' AND slug='brand-bd0eeac9e747' AND status='active' AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Brand identity changed: box-bbq';END IF;
END $identity$;
